import re,os
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in sorted(fs):
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f); src=open(p).read()
        ms=list(re.finditer(r'^(?:private |protected )*(theorem|lemma|noncomputable def|def|abbrev)\s+([^\s({\[]+)', src, re.M))
        for idx,m in enumerate(ms):
            s=m.start(); e=ms[idx+1].start() if idx+1<len(ms) else len(src)
            stmt=src[s:e].split(':=')[0].split(' by\n')[0]
            if 'divUniversalFstWindow' in stmt and ('equivFun' in stmt or 'baseChange' in stmt or 'Submodule.map' in stmt):
                print(f"{p}:{src[:s].count(chr(10))+1}  {m.group(2)}")
